# !/usr/bin/env python3
"""
Collegia Scraper App Auto-Installer
Generates all views, backend scraping pipelines (Attendance, Timetable, Marks, Assignments), templates, and routes.
Run this script in the root directory of your Django project (where manage.py is located).
"""

import os
import base64

FILE_DATA = {'scraper_app/__init__.py': '', 'scraper_app/apps.py': 'ZnJvbSBkamFuZ28uYXBwcyBpbXBvcnQgQXBwQ29uZmlnCgoKY2xhc3MgU2NyYXBlckFwcENvbmZpZyhBcHBDb25maWcpOgogICAgbmFtZSA9ICdzY3JhcGVyX2FwcCcK', 'scraper_app/scraper_backend.py': '', 'scraper_app/urls.py': '', 'scraper_app/views.py': '', 'scraper_app/templates/scraper_app/login.html': '', 'scraper_app/templates/scraper_app/enter_password.html': '', 'scraper_app/templates/scraper_app/dashboard.html': '', 'parse_debug.py': ''}

def install():
    print("==========================================================")
    print("       COLLEGIA FULL FEATURE SUITE AUTO-INSTALLER         ")
    print("==========================================================")
    print("[i] Starting installation...")
    
    # 1. Check if we are in the correct Django root directory
    if not os.path.exists("manage.py"):
        print("[Error] manage.py not found in current directory!")
        print("[Error] Please place and run this script in your main project folder.")
        return
        
    # 2. Write all files
    for path, b64_content in FILE_DATA.items():
        # Create directory if it doesn't exist
        dir_name = os.path.dirname(path)
        if dir_name and not os.path.exists(dir_name):
            os.makedirs(dir_name, exist_ok=True)
            print(f"[✔] Created directory: {dir_name}")
            
        # Decode and write content
        content = base64.b64decode(b64_content.encode('utf-8'))
        with open(path, 'wb') as f:
            f.write(content)
        print(f"[✔] Written file: {path}")
        
    print("----------------------------------------------------------")
    print("[✔] INSTALLATION SUCCESSFUL! All features compiled!        ")
    print("==========================================================")
    print("👉 Next Steps:")
    print("1. Add 'scraper_app' to INSTALLED_APPS in myproject/settings.py")
    print("2. Add path('collegia/', include('scraper_app.urls')) in myproject/urls.py")
    print("3. Run 'python manage.py migrate' in your terminal")
    print("4. Start your server using 'python manage.py runserver'")
    print("==========================================================")

if __name__ == '__main__':
    install()
